import re

from lfx.custom.custom_component.component import Component
from lfx.io import HandleInput, Output
from lfx.schema.data import Data
from lfx.schema.message import Message


class MarkdownTableFixer(Component):
    display_name = "Markdown Table Fixer"
    description = "Repair simple Markdown table formatting before chunking."
    icon = "table"
    name = "MarkdownTableFixer"

    inputs = [
        HandleInput(
            name="input_data",
            display_name="Markdown Input",
            input_types=["Data", "Message"],
            required=True,
        )
    ]

    outputs = [
        Output(
            display_name="Fixed Markdown",
            name="data",
            method="fix_tables",
        )
    ]

    def _get_text_and_meta(self):
        value = self.input_data

        if isinstance(value, Data):
            text = value.get_text() if hasattr(value, "get_text") else getattr(value, "text", "")
            meta = dict(value.data or {})
            return text, meta

        if isinstance(value, Message):
            return value.text or "", {}

        return str(value), {}

    def _is_table_line(self, line: str) -> bool:
        stripped = line.strip()
        return stripped.startswith("|") and stripped.endswith("|") and stripped.count("|") >= 2

    def _split_cells(self, line: str):
        stripped = line.strip().strip("|")
        return [cell.strip() for cell in stripped.split("|")]

    def _make_row(self, cells):
        return "| " + " | ".join(cells) + " |"

    def _make_separator(self, n_cols: int):
        return "| " + " | ".join(["---"] * n_cols) + " |"

    def _is_separator_row(self, line: str) -> bool:
        cells = self._split_cells(line)
        if not cells:
            return False
        return all(re.fullmatch(r":?-{3,}:?", c.strip()) for c in cells)

    def _fix_table_block(self, lines):
        if len(lines) < 2:
            return lines

        rows = [self._split_cells(line) for line in lines]
        max_cols = max(len(row) for row in rows)

        normalized = []
        for row in rows:
            if len(row) < max_cols:
                row = row + [""] * (max_cols - len(row))
            elif len(row) > max_cols:
                row = row[:max_cols]
            normalized.append(row)

        output = []

        # Header row.
        output.append(self._make_row(normalized[0]))

        # Separator row.
        if len(lines) > 1 and self._is_separator_row(lines[1]):
            output.append(self._make_separator(max_cols))
            start_idx = 2
        else:
            output.append(self._make_separator(max_cols))
            start_idx = 1

        for row in normalized[start_idx:]:
            output.append(self._make_row(row))

        return output

    def fix_tables(self) -> Data:
        text, meta = self._get_text_and_meta()

        lines = text.split("\n")
        out = []
        table_block = []

        def flush_table():
            nonlocal table_block
            if table_block:
                out.extend(self._fix_table_block(table_block))
                table_block = []

        for line in lines:
            if self._is_table_line(line):
                table_block.append(line)
            else:
                flush_table()
                out.append(line)

        flush_table()

        fixed_text = "\n".join(out).strip()
        meta["tables_fixed"] = True

        return Data(text=fixed_text, data=meta)

import re
import uuid

from lfx.custom.custom_component.component import Component
from lfx.io import HandleInput, Output
from lfx.schema.data import Data
from lfx.schema.dataframe import DataFrame
from lfx.schema.message import Message


class ChunkMetadataBuilder(Component):
    display_name = "Chunk Metadata Builder"
    description = "Add doc/page/section/content_type metadata to chunks before vector ingestion."
    icon = "tags"
    name = "ChunkMetadataBuilder"

    inputs = [
        HandleInput(
            name="chunks",
            display_name="Chunks",
            input_types=["Data", "DataFrame", "Table", "Message"],
            required=True,
        )
    ]

    outputs = [
        Output(
            display_name="Chunks With Metadata",
            name="dataframe",
            method="build_metadata",
        )
    ]

    def _extract_text(self, item):
        if isinstance(item, Data):
            return item.get_text() if hasattr(item, "get_text") else getattr(item, "text", "")
        if isinstance(item, Message):
            return item.text or ""
        if isinstance(item, dict):
            return item.get("text") or item.get("content") or str(item)
        return str(item)

    def _extract_meta(self, item):
        if isinstance(item, Data):
            return dict(item.data or {})
        if isinstance(item, dict):
            return {k: v for k, v in item.items() if k not in ["text", "content"]}
        return {}

    def _to_items(self):
        value = self.chunks

        if isinstance(value, DataFrame):
            items = []
            try:
                records = value.to_dict(orient="records")
                for row in records:
                    text = row.get("text", "")
                    meta = {k: v for k, v in row.items() if k != "text"}
                    items.append(Data(text=text, data=meta))
                return items
            except Exception:
                pass

            try:
                return list(value)
            except Exception:
                return [Data(text=str(value), data={})]

        if isinstance(value, list):
            return value

        return [value]

    def _detect_content_type(self, text: str) -> str:
        stripped = text.strip()

        if "[IMAGE_DESCRIPTION" in stripped or stripped.startswith("Image description:"):
            return "image_description"

        table_lines = [
            line for line in stripped.splitlines()
            if line.strip().startswith("|") and line.strip().endswith("|")
        ]
        if len(table_lines) >= 2:
            return "table"

        return "text"

    def _detect_section_title(self, text: str):
        for line in text.splitlines():
            line = line.strip()
            if re.match(r"^#{1,6}\s+\S+", line):
                return re.sub(r"^#{1,6}\s+", "", line).strip()
        return None

    def _detect_page_markers(self, text: str):
        pages = []
        patterns = [
            r"---\s*PAGE\s+(\d+)\s*---",
            r"---\s*PAGE\s+BREAK\s*---",
            r"Page\s+(\d+)",
            r"Trang\s+(\d+)",
        ]

        for pattern in patterns:
            for match in re.finditer(pattern, text, flags=re.IGNORECASE):
                if match.groups():
                    try:
                        pages.append(int(match.group(1)))
                    except Exception:
                        pass

        if pages:
            return min(pages), max(pages)

        return None, None

    def build_metadata(self) -> DataFrame:
        items = self._to_items()

        output = []

        fallback_doc_id = f"doc_{uuid.uuid4().hex[:8]}"

        for idx, item in enumerate(items, start=1):
            text = self._extract_text(item).strip()
            meta = self._extract_meta(item)

            if not text:
                continue

            doc_id = meta.get("doc_id") or meta.get("file_name") or fallback_doc_id
            file_name = meta.get("file_name") or meta.get("source") or ""

            page_start, page_end = self._detect_page_markers(text)

            content_type = self._detect_content_type(text)
            section_title = self._detect_section_title(text)

            chunk_id = f"{doc_id}_chunk_{idx:05d}"

            new_meta = dict(meta)
            new_meta.update(
                {
                    "doc_id": str(doc_id),
                    "chunk_id": chunk_id,
                    "chunk_index": idx,
                    "content_type": content_type,
                    "section_title": section_title or "",
                    "page_start": page_start or "",
                    "page_end": page_end or "",
                    "source": f"{file_name} chunk {idx}" if file_name else f"{doc_id} chunk {idx}",
                }
            )

            output.append(Data(text=text, data=new_meta))

        return DataFrame(output)
